import {Config, Field} from 'alinea'

export const Author = Config.type('Author', {
  fields: {
    title: Field.text('Name', {required: true, width: 0.5}),
    path: Field.path('Path', {required: true, width: 0.5})
  }
})

import {Config, Field} from 'alinea'

export default Config.type('Path field', {
  fields: {
    title: Field.text('Title', {
      initialValue: 'My first post',
      required: true, width: 0.5
    }),
    path: Field.path('Path', {
      required: true, width: 0.5
    })
  }
})

import {Config, Field} from 'alinea'

export const Section = Config.type('Section', {
  fields: {
    heading: Field.text('Heading', {width: 0.5}),
    anchor: Field.path('Anchor', {from: 'heading', width: 0.5})
  }
})

import {Config, Field} from 'alinea'

export default Config.type('Path field (from)', {
  fields: {
    heading: Field.text('Heading', {
      initialValue: 'Opening hours',
      width: 0.5
    }),
    anchor: Field.path('Anchor', {
      from: 'heading',
      width: 0.5
    })
  }
})

import {Config, Field} from 'alinea'

export const Home = Config.document('Home', {
  fields: {
    path: Field.path('Path', {readOnly: true, width: 0.5})
  }
})

export const pages = Config.root('Pages', {
  contains: ['Page'],
  children: {
    index: Config.page({type: Home, fields: {title: 'Home'}})
  }
})
